      ) as "position"
    from
      "asset_landmark"
      inner join "landmark" on "landmark"."id" = "asset_landmark"."landmarkId"
      inner join "asset" on "asset"."id" = "asset_landmark"."assetId"
    where
      "asset"."ownerId" = any ($2::uuid[])
