          where
            asset_lock."assetId" = "asset"."id"
        )
      )
      and "asset"."deletedAt" is null
  )
select
  "landmark"."id",
  "landmark"."name",
  "landmark"."kind",
  "landmark"."latitude",
  "landmark"."longitude",
  count(*) as "assetCount",
  min("asset"."localDateTime") as "firstTakenAt",
  max("asset"."localDateTime") as "lastTakenAt",
  (
    array_agg(
      asset.id
      order by
        asset."localDateTime" desc
    )
  ) [1] as "coverAssetId",
  mode() within group (
    order by
      asset_exif.city
  ) as "city",
  mode() within group (
    order by
      asset_exif.state
  ) as "state",
  mode() within group (
    order by
      asset_exif.country
  ) as "country"
from
  "matched"
  inner join "landmark" on "landmark"."id" = "matched"."landmarkId"
  inner join "asset" on "asset"."id" = "matched"."assetId"
  inner join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
group by
  "landmark"."id"
having
  bool_or(matched.position = 1)
  or landmark."radiusM" > $3
order by
  "assetCount" desc,
