-- SearchRepository.searchSmartV3 (baseline)
begin
set
  local hnsw.ef_search = 100
select
  "asset"."id",
  "asset"."updateId",
  "asset"."createdAt",
  "asset"."updatedAt",
  "asset"."deletedAt",
  "asset"."status",
  "asset"."checksum",
  "asset"."checksumAlgorithm",
  "asset"."duplicateId",
  "asset"."duration",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."isExternal",
  "asset"."isFavorite",
  "asset"."isOffline",
  "asset"."isEdited",
  "asset"."visibility",
  "asset"."libraryId",
  "asset"."livePhotoVideoId",
  "asset"."localDateTime",
  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height",
  exists (
    select
      1
    from
      asset_lock
    where
      asset_lock."assetId" = "asset"."id"
  ) as "isLocked"
from
  "asset"
  left join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
  inner join "smart_search" on "asset"."id" = "smart_search"."assetId"
where
  (
    "asset"."ownerId" = any ($1::uuid[])
    and (
      "asset"."ownerId" = $2::uuid
      or (
        "asset"."deletedAt" is null
        and "asset"."visibility" in ('timeline', 'hidden')
      )
    )
  )
  and (
    not exists (
      select
        1
      from
        asset_lock
      where
        asset_lock."assetId" = "asset"."id"
    )
    or "asset"."ownerId" = $3::uuid
  )
  and (
    "asset"."ownerId" = $4::uuid
    or "asset"."deletedAt" is null
  )
  and true
order by
  least(
    (smart_search.embedding <=> $5),
    coalesce(
      $6 * (
        select
          embedding <=> $7
        from
          smart_search_description
        where
          "assetId" = asset.id
      ),
      (smart_search.embedding <=> $8)
    )
  ),
  "asset"."id" asc
limit
  $9
offset
  $10
commit

